解：semaphore empty=N;//可存放的邮件数
semaphore full=0;//已存入邮件数
semaphore mutex=1;//邮箱操作互斥信号量
void A(){
while(1){
wait(full);
wait(mutex);
//读邮件，删邮件
signal(mutex);
signal(empty);
}
}

void B(){
while(1){
wait(empty);
wait(mutex);
//发邮件，存邮件
signal(mutex);
signal(full);
}
}

